INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 20, 'theory', 'Quiz: virtual memory');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 0, 'What happens when a virtual address is translated into a physical one?', '["All the address bits change", "The page number is replaced by the frame number, and the offset within the page stays the same", "Only the offset changes", "The address is written to disk"]', 1, 'A page and a frame are the same size, so the low bits (the offset) are copied as they are.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 1, 'Why are page tables made multilevel?', '["Translation is faster that way", "To avoid storing a huge flat table: tables for empty regions are simply not created", "For security reasons only", "The operating system requires it"]', 1, 'A flat table for a 48-bit address would take 512 GiB per process; with four levels of 512 entries only the branches that are needed get allocated.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 2, 'What does the TLB store?', '["Recent \"page → frame\" translations", "The contents of RAM", "Processor instructions", "The list of processes"]', 0, 'A TLB hit gives the frame in one cycle, and the table walk is needed only on a miss.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 3, 'What is thrashing?', '["Processor overheating", "The working set doesn''t fit in memory: pages are constantly evicted and immediately loaded again", "An error in the page table", "Running out of disk space"]', 1, 'The system spends almost all its time swapping with the disk; adding memory or running fewer programs helps.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 20, 4, 'Why is copy-on-write needed after fork?', '["To slow down the child process", "Frames stay shared until someone writes — process creation is cheap and saves memory", "To encrypt pages", "To clear the cache"]', 1, 'A copy of the frame is made only at the first write; the rest of the time the parent and child share the same pages.');
